class Solution {
    static const long long MOD = 1000000007;
    long long modPow(long long a, long long e) {
        long long r = 1;
        while (e) {
            if (e & 1) r = r * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return r;
    }
public:
    int sumDecoded(vector<long long>& nums) {
        long long ans = 0;
        for (long long v : nums) {
            int width = v % 10;
            string digits = to_string(v / 10);
            long long x = stoll(digits.substr(0, width));
            long long y = stoll(digits.substr(width));
            ans = (ans + modPow(x, y)) % MOD;
        }
        return (int)ans;
    }
};
